  // Find where "Add pet criteria" is
  const heading = Array.from(document.querySelectorAll('*')).find(el => el.textContent?.trim() === 'Add pet criteria' && el.children.length === 0);
  if (!heading) return { found: false };

  // Get its modal container
  let container = heading;
  while (container.parentElement && container.parentElement !== document.body) {
    container = container.parentElement;
    if (getComputedStyle(container).position === 'fixed') break;
  }

  // Find all checkboxes or clickable filter items
  const items = Array.from(container.querySelectorAll('input, label, button, [role="checkbox"]')).map(el => ({
    tagName: el.tagName,
    type: el.type,
    role: el.getAttribute('role'),
    ariaChecked: el.getAttribute('aria-checked'),
    text: el.textContent?.trim(),
    className: el.className,
    checked: el.checked
  }));

  return {
    found: true,
    containerClass: container.className,
    itemsCount: items.length,
    items: items.filter(i => i.text && (i.text.includes('Senior') || i.text.includes('Spay') || i.text.includes('Save')))
  };
});

