    className: el.className,
    checked: el.checked
  }));

  return {
    found: true,
    containerClass: container.className,
    itemsCount: items.length,
    items: items.filter(i => i.text && (i.text.includes('Senior') || i.text.includes('Spay') || i.text.includes('Save')))
  };
});

